# -*- coding: utf-8 -*-
DEEPA = {
"IAS 8": [
("السياسات المحاسبية: متى تُغيَّر؟", [
"السياسات المحاسبية هي المبادئ والأسس والقواعد التي تطبّقها المنشأة في إعداد قوائمها. يجب تطبيق السياسة نفسها على المعاملات المتشابهة، ولا يجوز تغييرها إلا في حالتين: أن يفرض التغيير معيار دولي جديد أو تعديل عليه، أو أن يؤدي التغيير إلى معلومات أكثر موثوقية وملاءمة عن أثر المعاملات في المركز المالي والأداء والتدفقات.",
"ليس تغييرًا في السياسة أن تطبّق سياسة جديدة على معاملات لم تكن تحدث من قبل، أو على معاملات غير جوهرية. ومثال التغيير المسموح: التحول من طريقة الوارد أولًا صادر أولًا إلى المتوسط المرجّح في المخزون إذا كانت الثانية تعكس نمط الاستهلاك بصورة أدق."]),
("التغيير في السياسة: التطبيق بأثر رجعي", [
"القاعدة العامة أن يُطبَّق التغيير في السياسة بأثر رجعي، أي كأن السياسة الجديدة كانت مطبقة دائمًا. وتُعدَّل الأرصدة الافتتاحية لكل بند متأثر في حقوق الملكية للفترة الأقدم المعروضة، وتُعاد صياغة أرقام المقارنة. ولا يمر الأثر في الربح أو الخسارة للفترة الحالية.",
"إذا كان تحديد الأثر التراكمي أو أثر الفترات السابقة غير ممكن عمليًا، يُطبَّق التغيير من أقدم تاريخ ممكن، وقد يكون مستقبليًا فقط. ويجب الإفصاح عن طبيعة التغيير وسببه ومبلغ التعديل لكل بند في القوائم وللعائد على السهم إن وُجد، وأن يُعرض مركز مالي ثالث في بداية أقدم فترة مقارنة عند تأثر الأرصدة الافتتاحية جوهريًا."]),
("التغيير في التقديرات المحاسبية", [
"التقدير المحاسبي هو مبلغ نقدي خاضع لعدم تأكد في القياس، مثل مخصص الديون المشكوك فيها، أو العمر الإنتاجي للأصل، أو القيمة العادلة، أو مخصص الضمان. تغيير التقدير ينتج عن معلومات جديدة أو تطورات، وليس تصحيحًا لخطأ.",
"يُعالج التغيير في التقدير بأثر مستقبلي، فيدخل في الربح أو الخسارة في فترة التغيير والفترات اللاحقة المتأثرة، ولا تُعدَّل أرقام المقارنة. مثال: أصل تكلفته 100,000 وعمره 10 سنوات بلا خردة، وبعد 4 سنوات تقرر أن العمر المتبقي 3 سنوات فقط. القيمة الدفترية 60,000، فيصبح قسط الإهلاك السنوي 20,000 بدل 10,000.",
"قيد: من حـ/ مصروف الإهلاك 20,000 — إلى حـ/ مجمع إهلاك الأصل 20,000 (عن كل سنة من السنوات الثلاث المتبقية)."]),
("تصحيح أخطاء الفترات السابقة", [
"الأخطاء قد تكون أخطاء حسابية، أو تطبيقًا خاطئًا لسياسة، أو إغفالًا لحقائق، أو احتيالًا. تُصحَّح الأخطاء الجوهرية للفترات السابقة بأثر رجعي بإعادة عرض أرقام المقارنة، أو بتعديل الأرصدة الافتتاحية لأقدم فترة معروضة إذا حدث الخطأ قبلها.",
"يُفصح عن طبيعة الخطأ ومبلغ التصحيح لكل بند وللعائد على السهم. ويختلف هذا عن تعديل التقدير الذي لا يُعاد به عرض الفترات السابقة. نصيحة عملية: وثّق سبب التصنيف (سياسة أم تقدير أم خطأ) لأن التصنيف يحدد المعالجة والإفصاح، ويطّلع عليه المراجع عادةً."]),
],
"IAS 10": [
("تعريف الأحداث بعد فترة التقرير", [
"هي أحداث مواتية أو غير مواتية تقع بين نهاية فترة التقرير وتاريخ إجازة القوائم المالية للإصدار. وتاريخ الإجازة هو التاريخ الذي يعتمد فيه مجلس الإدارة أو الجهة المخوّلة القوائم للنشر، وليس تاريخ تقرير المراجع بالضرورة.",
"تنقسم إلى نوعين: أحداث معدِّلة تقدّم دليلًا على ظروف كانت قائمة في نهاية الفترة، وأحداث غير معدِّلة تدل على ظروف نشأت بعد نهاية الفترة."]),
("الأحداث المعدِّلة", [
"تستوجب تعديل المبالغ المعترف بها في القوائم. من أمثلتها: قرار محكمة بعد نهاية الفترة يؤكد وجود التزام قائم في تاريخ التقرير، فيُعدَّل المخصص أو يُعترف بواحد جديد. وكذلك وصول معلومات بعد نهاية الفترة تدل على انخفاض قيمة أصل في تاريخها، مثل إفلاس عميل بعد نهاية السنة يؤكد عدم قابلية رصيد المدين للتحصيل. وتحديد تكلفة أصول اشتُريت أو سعر بيع أصول بيعت قبل نهاية الفترة، واكتشاف احتيال أو أخطاء تبيّن أن القوائم غير صحيحة.",
"قيد: من حـ/ خسائر ائتمانية متوقعة (مصروف ديون معدومة) 80,000 — إلى حـ/ مخصص خسائر الذمم المدينة 80,000 (إفلاس عميل بعد نهاية السنة مع تأكيد الوضع المالي المتدهور قبلها)."]),
("الأحداث غير المعدِّلة والإفصاح", [
"لا تُعدَّل بها المبالغ، لكن يُفصح عنها إن كان إغفالها يؤثر في قرارات مستخدمي القوائم. وتشمل: دمج أعمال كبيرًا بعد نهاية الفترة، أو إعلان خطة لإيقاف عملية رئيسية، أو شراء أو بيع أصول كبيرة، أو تدمير مصنع بحريق بعد نهاية الفترة، أو تغيرًا كبيرًا في أسعار الأصول أو أسعار الصرف بعد التاريخ، أو الدخول في التزامات كبيرة.",
"يُفصح عن طبيعة الحدث وتقدير أثره المالي، أو بيان أن تقديره غير ممكن. ويُفصح كذلك عن تاريخ إجازة القوائم والجهة التي أجازتها."]),
("توزيعات الأرباح واستمرارية المنشأة", [
"توزيعات الأرباح على حملة الأسهم المعلنة بعد نهاية فترة التقرير لا تُعدّ التزامًا في تاريخ التقرير، فلا يُعترف بها، وإنما يُفصح عنها في الإيضاحات.",
"أما إذا اقتضى الحدث بعد نهاية الفترة أن الإدارة تنوي تصفية المنشأة أو إيقاف أعمالها أو أنها لا تملك بديلًا واقعيًا غير ذلك، فلا تُعدّ القوائم على أساس الاستمرارية بل تُعدّ على أساس آخر مناسب. وهذه من أخطر الأحداث اللاحقة وتستلزم إفصاحًا واضحًا."]),
],
"IAS 12": [
("مفهوم الضريبة المؤجلة", [
"الضريبة الجارية هي الضريبة المستحقة عن الربح الخاضع للضريبة للفترة. أما الضريبة المؤجلة فتنشأ من الفروق المؤقتة بين القيمة الدفترية للأصل أو الالتزام في القوائم المالية وأساسه الضريبي. تعتمد المنهجية على قائمة المركز المالي (طريقة الالتزام)، لا على قائمة الدخل.",
"الفروق المؤقتة الخاضعة للضريبة تُنشئ التزامات ضريبة مؤجلة، مثل أن يكون إهلاك الأصل ضريبيًا أسرع من المحاسبي. والفروق المؤقتة القابلة للخصم تُنشئ أصول ضريبة مؤجلة، مثل مخصص مصروف لا يُقبل ضريبيًا إلا عند دفعه."]),
("مثال محاسبي مبسّط", [
"آلة بتكلفة 100,000، وإهلاكها المحاسبي 20,000 سنويًا لخمس سنوات، بينما تسمح الأنظمة الضريبية بإهلاك 40,000 في السنة الأولى. في نهاية السنة الأولى القيمة الدفترية 80,000 والأساس الضريبي 60,000، فالفرق المؤقت 20,000. بمعدل ضريبة 20% ينشأ التزام مؤجل قدره 4,000.",
"قيد: من حـ/ مصروف ضريبة مؤجلة 4,000 — إلى حـ/ التزام ضريبة مؤجلة 4,000.",
"ينعكس الفرق في السنوات اللاحقة عندما يصبح الإهلاك المحاسبي أكبر من الضريبي، فيتناقص الالتزام المؤجل تدريجيًا إلى الصفر بنهاية عمر الأصل."]),
("أصول الضريبة المؤجلة وقابلية الاسترداد", [
"لا يُعترف بأصل الضريبة المؤجلة إلا إذا كان من المرجّح توفر أرباح خاضعة للضريبة مستقبلًا يمكن الاستفادة منها في خصم الفرق المؤقت أو الخسائر الضريبية المرحّلة. تُراجَع القيمة الدفترية للأصل في نهاية كل فترة تقرير وتُخفَّض إذا لم يعد استردادها مرجّحًا.",
"المنشأة التي لها تاريخ خسائر حديثة تحتاج دليلًا مقنعًا على أرباح مستقبلية، مثل التزامات مبيعات مؤكدة أو أرباح استثنائية معروفة، قبل أن تعترف بأصل على خسائر مرحّلة."]),
("المعدلات والعرض والإفصاح", [
"تُقاس الضريبة المؤجلة بالمعدلات المتوقع تطبيقها عند تحقق الأصل أو سداد الالتزام، استنادًا إلى معدلات صدرت أو صدر ما هو في حكمها في نهاية فترة التقرير. ولا يجوز خصم الأصول والالتزامات المؤجلة بمعدل خصم.",
"تُعرض أصول والتزامات الضريبة المؤجلة كبنود غير متداولة، ويجوز مقاصتها فقط إذا وُجد حق نظامي ملزم لمقاصة الضريبة الجارية وتعلقت بالسلطة الضريبية نفسها. ومن الإفصاحات المهمة مطابقة معدل الضريبة الفعلي مع المعدل النظامي، ومبالغ الخسائر الضريبية غير المعترف بأصل عنها."]),
],
"IAS 21": [
("العملة الوظيفية وعملة العرض", [
"العملة الوظيفية هي عملة البيئة الاقتصادية الرئيسية التي تعمل فيها المنشأة، وتحددها عوامل مثل العملة التي تؤثر في أسعار البيع، والعملة التي تُحدّد بها التكاليف الرئيسية، وعملة التمويل. أما عملة العرض فهي العملة التي تُعرض بها القوائم المالية، وقد تختلف عن الوظيفية.",
"بعد تحديد العملة الوظيفية لا تتغير إلا إذا تغيرت الظروف الأساسية، ويكون التغيير بأثر مستقبلي."]),
("المعاملات بالعملات الأجنبية", [
"تُسجَّل المعاملة بالعملة الأجنبية مبدئيًا بالعملة الوظيفية باستخدام سعر الصرف الفوري في تاريخ المعاملة. وفي نهاية كل فترة تقرير تُترجم البنود النقدية بسعر الإقفال، أما البنود غير النقدية المقاسة بالتكلفة التاريخية فتبقى بسعر تاريخ المعاملة، والمقاسة بالقيمة العادلة فتُترجم بسعر تاريخ تحديد القيمة العادلة.",
"تُسجَّل فروق الصرف على البنود النقدية في الربح أو الخسارة في الفترة التي تنشأ فيها. مثال: شراء بضاعة بـ 10,000 دولار والسعر 3.75 ريال، فيُسجَّل الدائنون بـ 37,500 ريال. إذا أصبح السعر عند السداد 3.76 تكون خسارة الصرف 100 ريال.",
"قيد: من حـ/ الدائنون 37,500 ومن حـ/ خسائر فروق العملة 100 — إلى حـ/ النقدية 37,600."]),
("ترجمة العمليات الأجنبية", [
"عند تجميع منشأة تابعة عملتها الوظيفية تختلف عن عملة العرض للمجموعة، تُترجم أصولها والتزاماتها بسعر الإقفال، وإيراداتها ومصروفاتها بسعر تاريخ المعاملة أو بمتوسط تقريبي مناسب، وتُسجّل فروق الترجمة الناتجة في الدخل الشامل الآخر وتُجمع في بند منفصل ضمن حقوق الملكية.",
"عند استبعاد العملية الأجنبية تُعاد فروق الترجمة المتراكمة المتعلقة بها من حقوق الملكية إلى الربح أو الخسارة كجزء من ربح أو خسارة الاستبعاد."]),
("اقتصاديات التضخم المرتفع وملاحظات تطبيقية", [
"إذا كانت العملة الوظيفية لمنشأة تابعة عملة اقتصاد شديد التضخم، يُطبَّق عليها معيار IAS 29 (إعداد التقارير في الاقتصادات ذات التضخم المرتفع) قبل الترجمة.",
"من الممارسات الجيدة: تحديد مصدر رسمي ثابت لأسعار الصرف، ووثّق سبب اختيار العملة الوظيفية، وراجع أثر فروق الصرف على الهوامش عند التسعير بالعملة الأجنبية، وراقب تعرضك لمخاطر العملة عبر تحليل الحساسية."]),
],
"IAS 38": [
("تعريف الأصل غير الملموس وشروط الاعتراف", [
"الأصل غير الملموس هو أصل غير نقدي قابل للتحديد وليس له وجود مادي، مثل البرمجيات والتراخيص وحقوق الامتياز وحقوق النشر والعلامات التجارية المشتراة. وللاعتراف به يجب أن يكون قابلًا للتحديد (منفصلًا أو ناتجًا عن حقوق تعاقدية أو نظامية)، وأن تسيطر المنشأة عليه، وأن يكون من المرجّح تدفق منافع اقتصادية مستقبلية منه، وأن يمكن قياس تكلفته بموثوقية.",
"الشهرة المتولدة داخليًا والعلامات التجارية والعناوين والقوائم التي تولّدها المنشأة داخليًا وقوائم العملاء لا يُعترف بها كأصول."]),
("البحث والتطوير", [
"تُحمَّل تكاليف مرحلة البحث على المصروفات عند حدوثها. أما تكاليف مرحلة التطوير فتُرسمل فقط عندما تُثبت المنشأة جميع ما يلي: الجدوى الفنية لإتمام الأصل، والنية لإتمامه واستخدامه أو بيعه، والقدرة على ذلك، وكيف سيولّد منافع اقتصادية مستقبلية، وتوفر الموارد الفنية والمالية، والقدرة على قياس النفقات بموثوقية.",
"مثال: شركة تطوّر تطبيقًا. تكلفة دراسة السوق وتجريب أفكار قبل إثبات الجدوى 60,000 تُصرف. وبعد إثبات الجدوى الفنية والتجارية تُرسمل تكاليف التطوير 200,000.",
"قيد: من حـ/ أصول غير ملموسة قيد التطوير 200,000 — إلى حـ/ النقدية 200,000. وقيد آخر: من حـ/ مصروف أبحاث 60,000 — إلى حـ/ النقدية 60,000."]),
("الإطفاء وانخفاض القيمة", [
"الأصل ذو العمر المحدد يُطفأ على عمره الإنتاجي بطريقة تعكس نمط استهلاك المنافع، والأصل ذو العمر غير المحدد لا يُطفأ، لكن يُختبر انخفاض قيمته سنويًا وكلما وُجد مؤشر. وتُراجع فترة الإطفاء وطريقته في نهاية كل سنة مالية على الأقل.",
"افتراض أن الإيراد أساس صحيح للإطفاء مدحوض في الغالب، إلا في حالات محدودة مثل ارتباط الأصل بالإيراد صراحة. ويُطبَّق IAS 36 لاختبار الانخفاض."]),
("النماذج اللاحقة وتكاليف المواقع الإلكترونية", [
"يجوز قياس الأصل لاحقًا بنموذج التكلفة (التكلفة ناقص الإطفاء والانخفاض)، أو بنموذج إعادة التقييم إذا وُجد سوق نشطة للأصل، وهو نادر في الأصول غير الملموسة.",
"تكاليف تطوير موقع إلكتروني: مرحلة التخطيط تُصرف، والتصميم والتطوير الفعلي تُرسمل إذا تحققت الشروط، وتكاليف المحتوى والإعلان والصيانة تُصرف عند حدوثها. وتُفصح المنشأة عن الأعمار الإنتاجية وطرق الإطفاء وإجمالي مصروفات البحث والتطوير."]),
],
"IAS 40": [
("ما هو العقار الاستثماري؟", [
"العقار الاستثماري أرض أو مبنى أو جزء منه تحتفظ به المنشأة لتحصيل إيجارات أو لزيادة قيمته الرأسمالية أو لكليهما، وليس للاستخدام في الإنتاج أو التوريد أو الأغراض الإدارية، ولا للبيع ضمن النشاط العادي (وإلا فهو مخزون).",
"العقار الذي يشغله المالك يُعالج وفق IAS 16. وإذا كان جزء من المبنى يُؤجَّر وجزء يستعمله المالك فيُعالج كل جزء على حدة إذا أمكن بيعهما أو تأجيرهما تمويليًا بصورة منفصلة، وإلا فهو استثماري فقط إذا كان الجزء المشغول غير جوهري."]),
("نموذجا القياس اللاحق", [
"تختار المنشأة سياسة واحدة لكل عقاراتها الاستثمارية: نموذج القيمة العادلة، أو نموذج التكلفة. في نموذج القيمة العادلة تُدرج الأرباح والخسائر الناتجة عن تغير القيمة العادلة في الربح أو الخسارة، ولا يُحتسب إهلاك. وفي نموذج التكلفة يُطبَّق الإهلاك وانخفاض القيمة كما في IAS 16، مع الإفصاح عن القيمة العادلة.",
"مثال: عقار استثماري بالقيمة العادلة 5,000,000 ارتفعت إلى 5,300,000 في نهاية السنة.",
"قيد: من حـ/ عقارات استثمارية 300,000 — إلى حـ/ أرباح تقييم عقارات استثمارية (الربح أو الخسارة) 300,000."]),
("التحويلات والاستبعاد", [
"يُحوَّل العقار من وإلى العقار الاستثماري فقط عند تغير الاستخدام، مثل بدء الإشغال من المالك أو انتهائه أو بدء التطوير بغرض البيع. عند التحويل من الاستثماري المقاس بالقيمة العادلة إلى عقار يشغله المالك تكون التكلفة المفترضة هي القيمة العادلة في تاريخ التغيير.",
"يُستبعد العقار عند البيع أو السحب الدائم من الاستخدام. ويُحسب الربح أو الخسارة على أنه الفرق بين صافي متحصلات الاستبعاد والقيمة الدفترية، ويُدرج في الربح أو الخسارة."]),
("إفصاحات مهمة", [
"من أبرزها: النموذج المستخدم، وطرق وافتراضات تحديد القيمة العادلة وما إذا اعتمدت على مقيّم مستقل مؤهل، وإيرادات الإيجار والمصاريف التشغيلية المباشرة، والقيود على إمكانية البيع أو التحويل، والالتزامات التعاقدية للشراء أو التطوير.",
"نصيحة: اعتمد تقييمًا دوريًا من مقيّم معتمد وفق معايير مهنية، ووثّق مدخلات التقييم (معدلات الرسملة، الإيجارات السوقية)، لأن التقديرات القائمة على مدخلات غير ملحوظة تخضع لإفصاحات IFRS 13 الموسّعة."]),
],
"IFRS 3": [
("ما هو دمج الأعمال؟", [
"دمج الأعمال هو معاملة أو حدث تحصل بموجبه المنشأة المستحوذة على السيطرة على عمل تجاري واحد أو أكثر. يشترط أن يشكّل ما يُستحوذ عليه عملًا تجاريًا، أي مجموعة متكاملة من الأنشطة والأصول تتضمن مدخلًا وعملية جوهرية تسهمان معًا في القدرة على إنتاج المخرجات. شراء أصل مفرد أو مجموعة أصول ليست عملًا تجاريًا يُحاسب وفق المعيار المناسب للأصل.",
"يُطبَّق طريقة الاستحواذ على جميع دمج الأعمال، ولا يشمل المعيار دمج منشآت تحت سيطرة مشتركة."]),
("خطوات طريقة الاستحواذ", [
"تتضمن: تحديد المستحوذ، وتحديد تاريخ الاستحواذ (تاريخ الحصول على السيطرة)، والاعتراف بالأصول المحددة المستحوذ عليها والالتزامات المتحملة وأي حصة غير مسيطرة وقياسها، ثم الاعتراف بالشهرة أو بربح الشراء بسعر مخفض وقياسه.",
"تُقاس الأصول والالتزامات القابلة للتحديد بقيمها العادلة في تاريخ الاستحواذ مع استثناءات محددة في المعيار مثل الضرائب المؤجلة ومنافع الموظفين. ويشمل ذلك الأصول غير الملموسة التي لم تكن مُعترفًا بها في دفاتر المُستحوَذ عليها كعلاقات العملاء والعلامات التجارية."]),
("حساب الشهرة بمثال", [
"اشترت شركة (أ) 100% من شركة (ب) مقابل 1,000,000 نقدًا. القيمة العادلة للأصول القابلة للتحديد 1,200,000 والالتزامات 500,000، فصافي الأصول المحددة 700,000. الشهرة = المقابل المحوَّل 1,000,000 - صافي الأصول 700,000 = 300,000.",
"قيد: من حـ/ الأصول القابلة للتحديد بقيمها العادلة 1,200,000 ومن حـ/ الشهرة 300,000 — إلى حـ/ الالتزامات 500,000 وإلى حـ/ النقدية 1,000,000.",
"إذا كان صافي الأصول أكبر من المقابل يُسمّى الفرق ربح شراء بسعر مخفض، ويُعاد أولًا التحقق من صحة القياسات ثم يُعترف به في الربح أو الخسارة. الشهرة لا تُطفأ، بل تُختبر سنويًا لانخفاض القيمة وفق IAS 36."]),
("الحصة غير المسيطرة وتكاليف الاستحواذ", [
"عند الاستحواذ على أقل من 100% تختار المنشأة لكل عملية بين قياس الحصة غير المسيطرة بالقيمة العادلة (فتنتج شهرة كاملة) أو بحصتها التناسبية من صافي الأصول القابلة للتحديد (شهرة جزئية).",
"تكاليف الاستحواذ مثل أتعاب المستشارين والمحامين والتقييم تُصرف في الفترة التي تحدث فيها ولا تُضاف إلى المقابل، أما تكاليف إصدار أسهم أو ديون فتُعالج وفق معايير الأدوات المالية. والمقابل المحتمل يُقاس بقيمته العادلة في تاريخ الاستحواذ ويُصنف التزامًا أو حقوق ملكية، وتُعاد قياسه لاحقًا إن كان التزامًا."]),
],
"IFRS 13": [
("تعريف القيمة العادلة", [
"القيمة العادلة هي السعر الذي يُستلم لبيع أصل أو يُدفع لتحويل التزام في معاملة منتظمة بين المشاركين في السوق في تاريخ القياس. وهي قياس قائم على السوق وليس قياسًا خاصًا بالمنشأة، لذلك تُستخدم الافتراضات التي كان سيستخدمها المشاركون في السوق، حتى لو كانت المنشأة تنوي استخدام الأصل بشكل مختلف.",
"المعيار يحدد كيف تُقاس القيمة العادلة حين تتطلب معايير أخرى ذلك أو تسمح به، ولا يحدد متى تُستخدم، ويستثني بعض البنود مثل معاملات الدفع على أساس الأسهم والإيجارات."]),
("السوق الرئيسية وأعلى وأفضل استخدام", [
"يُفترض أن المعاملة تتم في السوق الرئيسية للأصل أو الالتزام، أي السوق الأكبر حجمًا ونشاطًا. وإذا لم توجد سوق رئيسية فالسوق الأكثر مزايا. ولا تُعدَّل القيمة العادلة بتكاليف المعاملة، ولا تشمل تكاليف النقل إذا كان الموقع جزءًا من خصائص الأصل.",
"للأصول غير المالية يُراعى أعلى وأفضل استخدام للأصل من وجهة نظر المشاركين في السوق، مثل استخدام أرض لمشروع سكني بدلًا من الاحتفاظ بها فارغة إذا كان الاستخدام الأعلى ممكنًا ماديًا ونظاميًا ومجديًا ماليًا."]),
("تسلسل القيمة العادلة", [
"المستوى الأول: أسعار معلنة في أسواق نشطة لأصول أو التزامات مماثلة يمكن الوصول إليها، وهي أقوى الأدلة، مثل سعر سهم مدرج. المستوى الثاني: مدخلات غير الأسعار المعلنة يمكن ملاحظتها للأصل أو الالتزام بشكل مباشر أو غير مباشر، مثل أسعار فائدة ومنحنيات عائد. المستوى الثالث: مدخلات غير ملحوظة، مثل توقعات تدفقات المنشأة، وتُستخدم فقط عند غياب المدخلات الملحوظة.",
"تُصنَّف القيمة العادلة كاملة ضمن أدنى مستوى لمدخل جوهري لقياسها. وكلما زاد الاعتماد على المستوى الثالث زادت متطلبات الإفصاح، بما فيها مطابقة الأرصدة وتحليل الحساسية."]),
("أساليب التقييم والإفصاح", [
"تستخدم المنشأة أسلوبًا أو أكثر من الأساليب الملائمة: أسلوب السوق (مقارنة بمعاملات مماثلة)، وأسلوب الدخل (خصم التدفقات أو الأرباح المستقبلية إلى قيمة حالية)، وأسلوب التكلفة (تكلفة إحلال الأصل مع تعديل التقادم). ويُعظَّم استخدام المدخلات الملحوظة ويُقلَّل استخدام غير الملحوظة.",
"من الإفصاحات: أساليب التقييم والمدخلات المستخدمة لكل فئة، ومستوى التسلسل، وأسباب أي تغيير في أسلوب التقييم، والتحويلات بين المستويات. نصيحة: احتفظ بملف توثيق لكل تقييم جوهري يتضمن المصدر والتاريخ والافتراضات، لأن المراجعين يركزون عليها."]),
],
}
